@once
<style>
.plyr-journey-modal[hidden],.plyr-journey-state[hidden],.plyr-journey-frame[hidden]{display:none!important}.plyr-journey-modal{position:fixed;inset:0;z-index:100510;display:grid;place-items:center;padding:18px;background:rgba(2,6,23,.72);backdrop-filter:blur(7px)}.plyr-journey-panel{width:min(760px,100%);max-height:min(900px,calc(100vh - 30px));display:flex;flex-direction:column;background:#fff;border:1px solid #e5e7eb;border-radius:22px;box-shadow:0 28px 80px rgba(0,0,0,.3);overflow:hidden;color:#101828}.plyr-journey-head{display:flex;align-items:flex-start;gap:14px;padding:18px 20px;border-bottom:1px solid #eaecf0;background:linear-gradient(135deg,#fff7f3,#fff)}.plyr-journey-badge{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;background:#ffebe5;color:#ff5c35;font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.plyr-journey-title{margin:5px 0 0;font-size:23px;line-height:1.1;font-weight:900;letter-spacing:-.03em}.plyr-journey-copy{margin:6px 0 0;color:#667085;font-size:12.5px;line-height:1.45}.plyr-journey-close{margin-left:auto;width:38px;height:38px;display:grid;place-items:center;border:1px solid #e4e7ec;border-radius:11px;background:#fff;color:#344054;font-size:22px;cursor:pointer;flex:0 0 auto}.plyr-journey-body{position:relative;min-height:390px;overflow:auto;background:#f8fafc}.plyr-journey-frame{display:block;width:100%;min-height:650px;border:0;background:#fff}.plyr-journey-state{min-height:390px;display:grid;place-items:center;padding:34px;text-align:center}.plyr-journey-state-inner{max-width:440px}.plyr-journey-spinner{width:38px;height:38px;margin:0 auto 16px;border-radius:50%;border:4px solid #fee4dc;border-top-color:#ff6338;animation:plyrJourneySpin .8s linear infinite}.plyr-journey-state strong{display:block;font-size:17px}.plyr-journey-state span{display:block;margin-top:6px;color:#667085;font-size:13px;line-height:1.5}.plyr-journey-success{color:#067647}.plyr-journey-success-icon{width:52px;height:52px;margin:0 auto 14px;border-radius:50%;display:grid;place-items:center;background:#dcfae6;color:#067647;font-size:24px;font-weight:900}.plyr-journey-done,.plyr-journey-retry{margin-top:16px;border:0;border-radius:10px;padding:10px 16px;background:#ff6338;color:#fff;font-weight:800;cursor:pointer}.plyr-journey-error{color:#b42318}.plyr-journey-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 18px;border-top:1px solid #eaecf0;background:#fff;color:#667085;font-size:11.5px}.plyr-journey-foot strong{color:#344054}@keyframes plyrJourneySpin{to{transform:rotate(360deg)}}@media(max-width:640px){.plyr-journey-modal{padding:0;place-items:stretch}.plyr-journey-panel{width:100%;max-height:100vh;height:100vh;border-radius:0}.plyr-journey-head{padding:14px 15px}.plyr-journey-title{font-size:20px}.plyr-journey-body{flex:1}.plyr-journey-frame{min-height:760px}.plyr-journey-foot{padding-bottom:max(11px,env(safe-area-inset-bottom))}}
</style>
<div class="plyr-journey-modal" data-plyrcard-my-journey-modal data-start-url="{{ route('billing.my-journey.start') }}" data-status-url="{{ route('billing.my-journey.status') }}" hidden>
  <div class="plyr-journey-panel" role="dialog" aria-modal="true" aria-labelledby="plyr-journey-title">
    <header class="plyr-journey-head"><div><span class="plyr-journey-badge">My Journey</span><h2 class="plyr-journey-title" id="plyr-journey-title">Upgrade to My Journey</h2><p class="plyr-journey-copy">Activate your $49/month recruiting workspace. Payment and billing details are linked to your existing PLYRCARD account automatically.</p></div><button class="plyr-journey-close" type="button" data-plyrcard-my-journey-close aria-label="Close">×</button></header>
    <div class="plyr-journey-body">
      <div class="plyr-journey-state" data-plyrcard-my-journey-loading><div class="plyr-journey-state-inner"><div class="plyr-journey-spinner"></div><strong>Preparing secure checkout</strong><span>Connecting this membership to your existing billing profile…</span></div></div>
      <div class="plyr-journey-state" data-plyrcard-my-journey-success hidden><div class="plyr-journey-state-inner plyr-journey-success"><div class="plyr-journey-success-icon">✓</div><strong>My Journey is active</strong><span>Your payment was confirmed. PLYRCARD has updated your membership, subscription, and safe billing information.</span><button class="plyr-journey-done" type="button" data-plyrcard-my-journey-close>Done</button></div></div>
      <div class="plyr-journey-state" data-plyrcard-my-journey-error hidden><div class="plyr-journey-state-inner plyr-journey-error"><strong>Checkout could not be prepared</strong><span data-plyrcard-my-journey-error-copy>Please try again.</span><button class="plyr-journey-retry" type="button" data-plyrcard-my-journey-retry>Try Again</button></div></div>
      <iframe class="plyr-journey-frame" data-plyrcard-my-journey-frame src="about:blank" scrolling="no" id="82L4a2pfvspbMYWeD0zo" title="My Journey secure checkout" data-cookie-consent="true" data-cookie-consent-provider="auto" hidden></iframe>
    </div>
    <footer class="plyr-journey-foot"><span data-plyrcard-my-journey-status>Payment confirmation is checked automatically.</span><strong>Secure checkout</strong></footer>
  </div>
</div>
<script src="https://systems.plyrcard.com/js/form_embed.js" defer></script>
<script>
(()=>{if(window.__plyrcardMyJourneyCheckoutV1089)return;window.__plyrcardMyJourneyCheckoutV1089=true;const modal=document.querySelector('[data-plyrcard-my-journey-modal]');if(!modal)return;const frame=modal.querySelector('[data-plyrcard-my-journey-frame]'),panel=modal.querySelector('.plyr-journey-panel'),foot=modal.querySelector('.plyr-journey-foot'),loading=modal.querySelector('[data-plyrcard-my-journey-loading]'),success=modal.querySelector('[data-plyrcard-my-journey-success]'),error=modal.querySelector('[data-plyrcard-my-journey-error]'),errorCopy=modal.querySelector('[data-plyrcard-my-journey-error-copy]'),statusCopy=modal.querySelector('[data-plyrcard-my-journey-status]');let timer=null,started=0,starting=false;const csrf=()=>document.querySelector('meta[name="csrf-token"]')?.content||document.querySelector('input[name="_token"]')?.value||'';const show=t=>{[loading,success,error,frame].forEach(el=>{if(el)el.hidden=el!==t});panel?.classList.toggle('is-checkout',t===frame);if(foot)foot.hidden=t===frame};const stop=()=>{if(timer)clearTimeout(timer);timer=null};const close=()=>{stop();modal.hidden=true;document.documentElement.style.overflow=''};async function req(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest',...(opt.method&&opt.method!=='GET'?{'X-CSRF-TOKEN':csrf(),'Content-Type':'application/json'}:{})},...opt});const d=await r.json().catch(()=>({}));if(!r.ok||d.success===false)throw new Error(d.message||'Unable to continue.');return d}async function poll(){if(modal.hidden)return;if(Date.now()-started>12*60*1000){statusCopy.textContent='Checkout is still open. Complete payment to activate My Journey.';return}try{const d=await req(modal.dataset.statusUrl);if(d.completed){stop();show(success);statusCopy.textContent='Payment confirmed. Updating your PLYRCARD…';window.dispatchEvent(new CustomEvent('plyrcard:my-journey-upgraded',{detail:d}));setTimeout(()=>{if(!document.querySelector('[data-lr-drawer]'))window.location.reload()},900);return}statusCopy.textContent=d.message||'Waiting for payment confirmation…'}catch(_){statusCopy.textContent='Still checking payment confirmation…'}timer=setTimeout(poll,2500)}async function start(){if(starting)return;starting=true;stop();modal.hidden=false;document.documentElement.style.overflow='hidden';show(loading);statusCopy.textContent='Preparing secure checkout…';try{const d=await req(modal.dataset.startUrl,{method:'POST',body:'{}'});if(d.completed){show(success);statusCopy.textContent=d.message||'My Journey is active.';window.dispatchEvent(new CustomEvent('plyrcard:my-journey-upgraded',{detail:d}));return}if(!d.checkout_url)throw new Error(d.message||'Secure checkout is unavailable.');frame.src=d.checkout_url;show(frame);started=Date.now();statusCopy.textContent=d.message||'Complete checkout to continue.';timer=setTimeout(poll,1800)}catch(e){show(error);errorCopy.textContent=e.message||'Please try again.';statusCopy.textContent='Checkout was not started.'}finally{starting=false}}document.addEventListener('click',e=>{const opener=e.target.closest('[data-plyrcard-my-journey-open]');if(opener){e.preventDefault();start();return}if(e.target.closest('[data-plyrcard-my-journey-close]')){close();return}if(e.target.closest('[data-plyrcard-my-journey-retry]')){start();return}if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close()})})();
</script>
@endonce
